package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*;import com.lbos.commercecustomer.enums.ProductStatus; @Entity @Table(name="products",uniqueConstraints= @UniqueConstraint(name="uq_product_retailer_sku",columnNames={"retailer_id","sku"}),indexes={@Index(name="idx_products_category_id",columnList="category_id"),@Index(name="idx_products_status",columnList="status")}) public class Product {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="product_id") private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id") private ProductCategory category; @Column(name="retailer_id",nullable=false) private UUID retailerId; @Column(nullable=false,length=80) private String sku; @Column(name="product_name",nullable=false,length=200) private String name; @Column(columnDefinition="TEXT") private String description; @Column(name="unit_price",nullable=false,precision=12,scale=2) private BigDecimal unitPrice; @Column(name="stock_quantity",nullable=false) private int stock; @Enumerated(EnumType.STRING) @Column(name="status",nullable=false,length=15) private ProductStatus status=ProductStatus.ACTIVE; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; @Column(name="quality_flag",length=20) private String qualityFlag; @Column(name="low_stock_threshold") private Integer lowStockThreshold; /** Weight of ONE unit in kilograms. NULL (products created before weights existed, or no weight given) means {@link #DEFAULT_WEIGHT_KG}. */ @Column(name="weight_kg",precision=10,scale=3) private BigDecimal weightKg; public static final BigDecimal DEFAULT_WEIGHT_KG=BigDecimal.ONE; public BigDecimal getWeightKg(){return weightKg;} public void setWeightKg(BigDecimal v){weightKg=v;} /** The weight to use everywhere: the stored value, or 1 kg when none is stored. */ public BigDecimal effectiveWeightKg(){return weightKg==null?DEFAULT_WEIGHT_KG:weightKg;} @PrePersist void add(){var now=OffsetDateTime.now();createdAt=now;updatedAt=now;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public Product(){} public Long getId(){return id;} public void setId(Long v){id=v;} public ProductCategory getCategory(){return category;} public void setCategory(ProductCategory v){category=v;} public UUID getRetailerId(){return retailerId;} public void setRetailerId(UUID v){retailerId=v;} public String getSku(){return sku;} public void setSku(String v){sku=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public int getStock(){return stock;} public void setStock(int v){stock=v;} public ProductStatus getStatus(){return status;} public void setStatus(ProductStatus v){status=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;} public String getQualityFlag(){return qualityFlag;} public void setQualityFlag(String v){qualityFlag=v;} public Integer getLowStockThreshold(){return lowStockThreshold;} public void setLowStockThreshold(Integer v){lowStockThreshold=v;}}